<script setup lang="ts">
import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{projectApi}from'../api/project';import{approvalApi}from'../api/leave';import{statusLabel}from'../utils/status';
const route=useRoute(),data=ref<any>(),approval=ref<any>();onMounted(async()=>{data.value=((await projectApi.detail(Number(route.params.id)))as any).data;if(data.value.approvalInstanceId)approval.value=((await approvalApi.detail(data.value.approvalInstanceId))as any).data})
</script>
<template><div class="page-title"><h1>立项详情</h1><p>立项信息及两级审批时间线</p></div><el-card v-if="data"><el-descriptions :column="2" border><el-descriptions-item label="申请单号">{{data.applicationNo}}</el-descriptions-item><el-descriptions-item label="状态">{{statusLabel(data.businessStatus)}}</el-descriptions-item><el-descriptions-item label="项目名称">{{data.projectName}}</el-descriptions-item><el-descriptions-item label="负责人">{{data.projectOwner}}</el-descriptions-item><el-descriptions-item label="申请人">{{data.applicantName}}</el-descriptions-item><el-descriptions-item label="部门">{{data.departmentName}}</el-descriptions-item><el-descriptions-item label="计划周期">{{data.plannedStartDate}} 至 {{data.plannedEndDate}}</el-descriptions-item><el-descriptions-item label="预算">{{data.budget}}</el-descriptions-item><el-descriptions-item label="摘要" :span="2">{{data.summary}}</el-descriptions-item></el-descriptions></el-card><el-card v-if="approval" style="margin-top:18px"><template #header>审批状态：{{statusLabel(approval.status)}}</template><el-timeline><el-timeline-item v-for="item in approval.timeline" :key="item.id" :timestamp="item.handledAt||item.createdAt"><b>{{item.nodeName}} · {{statusLabel(item.status)}}</b><p v-if="item.comment">审批意见：{{item.comment}}</p></el-timeline-item></el-timeline></el-card></template>
